                target = getattr(target, arg)
            except AttributeError as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '[':
            try:
                target = target[arg]
            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'P':
            _get = scope[TargetRegistry].get_handler('get', target, path=scope[Path])
            try:
                target = _get(target, arg)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '(':
            args, kwargs = arg
            args = arg_val(target, args, scope)
            kwargs = arg_val(target, kwargs, scope)
            target = target(*args, **kwargs)
