                raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                                % (target.__class__.__name__, Path(*scope[Path]), e))
        elif op == 'X':
            def _recursive_iterate(obj):
                yield obj
                get_handler = scope[TargetRegistry].get_handler
                children = []
                _extend_children(children, obj, get_handler)
                for child in children:
                    for item in _recursive_iterate(child):
                        yield item
            try:
                target = list(_recursive_iterate(target))
            except Exception as e:
                raise TypeError('failed to recursively iterate on instance of type %r at %r (got %r)'
                                % (target.__class__.__name__, Path(*scope[Path]), e))
        elif op in ('+', '-', '*', '#', '/', '%', ':', '&', '|', '^'):
            op_map = {'+': operator.add, '-': operator.sub, '*': operator.mul,
                      '#': operator.floordiv, '/': operator.truediv, '%': operator.mod,
                      ':': operator.pow, '&': operator.and_, '|': operator.or_, '^': operator.xor}
            try:
                target = op_map[op](target, arg)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '~':
