                target = ~target
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '_':
            try:
                target = -target
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)

    if cur_t is A:
        scope[t_ops[2]] = target

    return target
